export const decodeText=s=>String(s??'').replace(/&#x([a-f\d]+);/gi,(_,n)=>String.fromCodePoint(parseInt(n,16))).replace(/&#(\d+);/g,(_,n)=>String.fromCodePoint(+n)).replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&').replace(/\[\[([^\]]+)\.gif\]\]/g,(_,n)=>'['+n.replaceAll('_',' ')+']');
export const normalizedCode=code=>String(code).replace(/-([TP]?)E(?=\d)/g,'-$1');
export const baseCode=code=>normalizedCode(code).replace(/(SSP|SSP\+|SEC\+?|SP\+?|OFR|ABR|IGP|HYR|MDR|BNP|RRR|SR|PR|S|R)$/,'');
export function createPresentation(all,seriesNames={},references={}){
 const byExact=new Map(),byBase=new Map();for(const c of all.filter(c=>c.language==='EN')){for(const [map,key] of [[byExact,normalizedCode(c.code)],[byBase,baseCode(c.code)]]){if(!map.has(key))map.set(key,[]);map.get(key).push(c);}}
 const compatible=(a,b)=>{const keys=['type','color',...(a.type==='Character'?['level','cost','power']:a.type==='Event'?['level','cost']:[])];return keys.every(key=>String(a[key]??'').trim()===String(b[key]??'').trim());};
 const entries=new Map();for(const c of all){const series=seriesNames[c.series]||'Series name unavailable';if(c.language!=='JP'){entries.set(c.id,{name:decodeText(c.name),series,traits:c.attributes.filter(t=>t&&t!=='-').map(decodeText),ability:c.ability.map(decodeText),kind:'original',source:c.source});continue;}
 const exact=(byExact.get(normalizedCode(c.code))||[]).filter(en=>compatible(c,en));const candidates=exact.length?exact:(byBase.get(baseCode(c.code))||[]).filter(en=>compatible(c,en));candidates.sort((a,b)=>(b.rarity===c.rarity)-(a.rarity===c.rarity)||(b.source==='Bushiroad English card list')-(a.source==='Bushiroad English card list'));
 const english=new Set(candidates.map(en=>decodeText(en.name))).size===1?candidates[0]:undefined,reference=references[c.code]||references[baseCode(c.code)],noTraits=!c.attributes.filter(t=>t&&t!=='-').length;
 entries.set(c.id,{name:english?decodeText(english.name):reference?.name||'English name unavailable',series,traits:english&&(english.attributes.length||noTraits)?english.attributes.filter(t=>t&&t!=='-').map(decodeText):noTraits?[]:null,ability:english?english.ability.map(decodeText):null,kind:english?'official':reference?'unofficial-reference':'missing',equivalent:english?.code,source:english?.source,reference:reference?.url,originalName:c.name,missing:!english&&!reference});}
 const aliases=new Map();for(const c of all){const name=entries.get(c.id).series;if(name==='Series name unavailable')continue;aliases.set(name.toLowerCase(),name);aliases.set(c.series.toLowerCase(),name);}return {get:c=>entries.get(typeof c==='string'?c:c.id),matches(c,query){const text=query.trim().toLowerCase(),p=entries.get(c.id),family=aliases.get(text);if(family)return p.series===family;return [p.series,p.name,c.name,c.code,c.series,...p.traits||[],...p.ability||[],...c.ability].join(' ').toLowerCase().includes(text);}};
}
